ungen werden gefördert."}, "excluded_embed_metadata_keys": ["pages", "heading_path", "sentence_ids", "tokens", "text"], "excluded_llm_metadata_keys": ["pages", "heading_path", "sentence_ids", "tokens", "text"], "relationships": {}, "metadata_template": "{key}: {value}", "metadata_separator": "
